(function(){"use strict";var root=document.documentElement;var motion=root.classList.contains("nh-motion");var pending=Array.prototype.slice.call(document.querySelectorAll("[data-nh-reveal], [data-nh-img]"));function reveal(){if(!pending.length)return;var line=window.innerHeight*.88;pending=pending.filter(function(el){if(el.getBoundingClientRect().top<line){el.classList.add("is-in");return false}return true})}if(!motion){pending.forEach(function(el){el.classList.add("is-in")});pending=[]}var header=document.querySelector(".ip-header");var parallax=Array.prototype.slice.call(document.querySelectorAll("[data-nh-parallax]"));var desktop=window.matchMedia("(min-width: 992px)");var ticking=false;function update(){ticking=false;if(header){header.classList.toggle("is-scrolled",window.pageYOffset>40)}reveal();if(!motion||!desktop.matches)return;var vh=window.innerHeight;parallax.forEach(function(el){var box=el.parentNode.getBoundingClientRect();if(box.bottom<0||box.top>vh)return;var p=(vh/2-(box.top+box.height/2))/(vh/2+box.height/2);var shift=Math.max(-1,Math.min(1,p))*box.height*.07;el.style.transform="translate3d(0,"+shift.toFixed(1)+"px,0)"})}function requestUpdate(){if(ticking)return;ticking=true;window.requestAnimationFrame(update)}window.addEventListener("scroll",requestUpdate,{passive:true});window.addEventListener("resize",requestUpdate);window.addEventListener("load",requestUpdate);update();var hero=document.getElementById("ipHero");if(hero){var current=hero.querySelector("[data-nh-hero-current]");var progress=hero.querySelector("[data-nh-progress]");var restartProgress=function(){if(!progress)return;progress.classList.remove("is-running");void progress.offsetWidth;progress.classList.add("is-running")};hero.addEventListener("slide.bs.carousel",function(event){if(current)current.textContent=String(event.to+1).padStart(2,"0");restartProgress()});restartProgress()}document.querySelectorAll(".ip-nh .ip-video[data-video]").forEach(function(box){function play(e){if(e.type==="keydown"&&e.key!=="Enter"&&e.key!==" ")return;e.preventDefault();if(box.querySelector("iframe"))return;var iframe=document.createElement("iframe");iframe.src="https://www.youtube.com/embed/"+encodeURIComponent(box.dataset.video)+"?autoplay=1";iframe.title="Ippon Group";iframe.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share";iframe.allowFullscreen=true;box.innerHTML="";box.appendChild(iframe);box.classList.add("is-playing")}box.addEventListener("click",play);box.addEventListener("keydown",play)});document.querySelectorAll("[data-nh-rail]").forEach(function(rail){var track=rail.querySelector("[data-nh-rail-track]");var controls=rail.querySelector("[data-nh-rail-controls]");var bar=rail.querySelector("[data-nh-rail-bar]");var prev=rail.querySelector("[data-nh-rail-prev]");var next=rail.querySelector("[data-nh-rail-next]");if(!track)return;function step(){var item=track.firstElementChild;if(!item)return track.clientWidth;var gap=parseFloat(window.getComputedStyle(track).columnGap)||0;return item.getBoundingClientRect().width+gap}function sync(){var max=track.scrollWidth-track.clientWidth;if(controls)controls.hidden=max<=1;if(prev)prev.disabled=track.scrollLeft<=1;if(next)next.disabled=track.scrollLeft>=max-1;if(bar&&track.scrollWidth){var share=track.clientWidth/track.scrollWidth;bar.style.width=share*100+"%";bar.style.transform="translateX("+(max>0?track.scrollLeft/max*(1/share-1)*100:0)+"%)"}}function go(dir){var from=track.scrollLeft;var by=dir*step();track.scrollBy({left:by,behavior:"smooth"});window.setTimeout(function(){if(Math.abs(track.scrollLeft-from)<1)track.scrollLeft=from+by;sync()},350)}if(prev)prev.addEventListener("click",function(){go(-1)});if(next)next.addEventListener("click",function(){go(1)});track.addEventListener("scroll",sync,{passive:true});window.addEventListener("resize",sync);window.addEventListener("load",sync);sync()})})();